-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create view public.feed_events with (security_invoker=true) as
 SELECT 'car'::text AS kind,
    c.id,
    c.created_at AS happened_at,
    c.id AS car_id,
    c.owner_id
   FROM public.cars c
  WHERE c.is_public
UNION ALL
 SELECT 'update'::text AS kind,
    p.id,
    p.published_at AS happened_at,
    p.car_id,
    p.author_id AS owner_id
   FROM public.activity_posts p
  WHERE p.published_at IS NOT NULL AND (p.car_id IS NULL OR (EXISTS ( SELECT 1
           FROM public.cars c
          WHERE c.id = p.car_id AND c.is_public)))
UNION ALL
 SELECT 'part'::text AS kind,
    l.id,
    l.created_at AS happened_at,
    l.source_car_id AS car_id,
    l.seller_id AS owner_id
   FROM public.listings l
  WHERE l.status = 'active'::text;

comment on view public.feed_events is 'Explore feed timeline: public cars, published build updates (with or without a car), active listings — one recency-ordered source (see src/lib/feed.ts).';

-- Grants
grant all on table public.feed_events to anon;
grant all on table public.feed_events to authenticated;
grant all on table public.feed_events to service_role;
